// Package textconv provides helpers for converting between text encodings and
// applying Unicode normalization forms.
package textconv

import (
	"fmt"
	"sort"
	"strings"

	"golang.org/x/text/encoding"
	"golang.org/x/text/encoding/charmap"
	"golang.org/x/text/encoding/japanese"
	"golang.org/x/text/encoding/korean"
	"golang.org/x/text/encoding/simplifiedchinese"
	"golang.org/x/text/encoding/traditionalchinese"
	"golang.org/x/text/encoding/unicode"
	"golang.org/x/text/transform"
	"golang.org/x/text/unicode/norm"
)

// encodings maps stable, case-insensitive names to their x/text encoding.
var encodings = map[string]encoding.Encoding{
	"utf-8":        unicode.UTF8,
	"utf-16":       unicode.UTF16(unicode.LittleEndian, unicode.UseBOM),
	"utf-16le":     unicode.UTF16(unicode.LittleEndian, unicode.IgnoreBOM),
	"utf-16be":     unicode.UTF16(unicode.BigEndian, unicode.IgnoreBOM),
	"windows-1252": charmap.Windows1252,
	"iso-8859-1":   charmap.ISO8859_1,
	"iso-8859-15":  charmap.ISO8859_15,
	"koi8-r":       charmap.KOI8R,
	"shift_jis":    japanese.ShiftJIS,
	"euc-jp":       japanese.EUCJP,
	"euc-kr":       korean.EUCKR,
	"gbk":          simplifiedchinese.GBK,
	"gb18030":      simplifiedchinese.GB18030,
	"big5":         traditionalchinese.Big5,
}

// Encodings returns the sorted list of supported encoding names.
func Encodings() []string {
	names := make([]string, 0, len(encodings))
	for name := range encodings {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

// Normalization forms accepted by Normalize.
const (
	NFC  = "NFC"
	NFD  = "NFD"
	NFKC = "NFKC"
	NFKD = "NFKD"
)

var forms = map[string]norm.Form{
	NFC:  norm.NFC,
	NFD:  norm.NFD,
	NFKC: norm.NFKC,
	NFKD: norm.NFKD,
}

// Decode converts data from the named encoding into a UTF-8 string.
func Decode(data []byte, encodingName string) (string, error) {
	enc, err := lookup(encodingName)
	if err != nil {
		return "", err
	}
	out, _, err := transform.String(enc.NewDecoder(), string(data))
	if err != nil {
		return "", fmt.Errorf("decode %s: %w", encodingName, err)
	}
	return out, nil
}

// Encode converts a UTF-8 string into data in the named encoding.
func Encode(s, encodingName string) ([]byte, error) {
	enc, err := lookup(encodingName)
	if err != nil {
		return nil, err
	}
	out, _, err := transform.Bytes(enc.NewEncoder(), []byte(s))
	if err != nil {
		return nil, fmt.Errorf("encode %s: %w", encodingName, err)
	}
	return out, nil
}

// Convert transcodes data from one encoding to another.
func Convert(data []byte, from, to string) ([]byte, error) {
	s, err := Decode(data, from)
	if err != nil {
		return nil, err
	}
	return Encode(s, to)
}

// Normalize applies the requested Unicode normalization form to s. The form is
// case-insensitive and defaults to NFC when empty.
func Normalize(s, form string) (string, error) {
	f, ok := forms[strings.ToUpper(form)]
	if !ok {
		if form == "" {
			f = norm.NFC
		} else {
			return "", fmt.Errorf("unsupported normalization form %q", form)
		}
	}
	return f.String(s), nil
}

func lookup(name string) (encoding.Encoding, error) {
	enc, ok := encodings[strings.ToLower(strings.TrimSpace(name))]
	if !ok {
		return nil, fmt.Errorf("unsupported encoding %q", name)
	}
	return enc, nil
}

package textconv

import "testing"

func TestDecodeWindows1252(t *testing.T) {
	// 0xE9 is 'é' in Windows-1252.
	got, err := Decode([]byte{0xE9}, "windows-1252")
	if err != nil {
		t.Fatalf("Decode: %v", err)
	}
	if got != "é" {
		t.Fatalf("Decode = %q, want %q", got, "é")
	}
}

func TestConvertRoundTrip(t *testing.T) {
	const want = "hello, 世界"
	data, err := Encode(want, "utf-16le")
	if err != nil {
		t.Fatalf("Encode: %v", err)
	}
	got, err := Decode(data, "utf-16le")
	if err != nil {
		t.Fatalf("Decode: %v", err)
	}
	if got != want {
		t.Fatalf("round trip = %q, want %q", got, want)
	}
}

func TestNormalize(t *testing.T) {
	// "é" as e + combining acute accent (NFD) normalizes to the precomposed
	// form under NFC.
	const decomposed = "e\u0301"
	got, err := Normalize(decomposed, "nfc")
	if err != nil {
		t.Fatalf("Normalize: %v", err)
	}
	if got != "\u00e9" {
		t.Fatalf("Normalize = %q, want %q", got, "\u00e9")
	}
}

func TestNormalizeUnknownForm(t *testing.T) {
	if _, err := Normalize("x", "NFX"); err == nil {
		t.Fatal("expected error for unknown form")
	}
}

func TestUnsupportedEncoding(t *testing.T) {
	if _, err := Decode(nil, "klingon"); err == nil {
		t.Fatal("expected error for unsupported encoding")
	}
}

// Command textconv converts text between encodings and applies Unicode
// normalization.
//
// Usage:
//
//	textconv convert -from windows-1252 -to utf-8 [file]
//	textconv normalize -form nfc [file]
//	textconv encodings
//
// When no file is given, input is read from standard input.
package main

import (
	"flag"
	"fmt"
	"io"
	"os"

	"example.com/textconv"
)

func main() {
	if len(os.Args) < 2 {
		usage()
		os.Exit(2)
	}

	var err error
	switch os.Args[1] {
	case "convert":
		err = runConvert(os.Args[2:])
	case "normalize":
		err = runNormalize(os.Args[2:])
	case "encodings":
		for _, name := range textconv.Encodings() {
			fmt.Println(name)
		}
	case "-h", "--help", "help":
		usage()
	default:
		fmt.Fprintf(os.Stderr, "textconv: unknown command %q\n", os.Args[1])
		usage()
		os.Exit(2)
	}

	if err != nil {
		fmt.Fprintln(os.Stderr, "textconv:", err)
		os.Exit(1)
	}
}

func runConvert(args []string) error {
	fs := flag.NewFlagSet("convert", flag.ExitOnError)
	from := fs.String("from", "utf-8", "source encoding")
	to := fs.String("to", "utf-8", "target encoding")
	if err := fs.Parse(args); err != nil {
		return err
	}
	data, err := readInput(fs.Args())
	if err != nil {
		return err
	}
	out, err := textconv.Convert(data, *from, *to)
	if err != nil {
		return err
	}
	_, err = os.Stdout.Write(out)
	return err
}

func runNormalize(args []string) error {
	fs := flag.NewFlagSet("normalize", flag.ExitOnError)
	form := fs.String("form", "nfc", "normalization form: NFC, NFD, NFKC, NFKD")
	if err := fs.Parse(args); err != nil {
		return err
	}
	data, err := readInput(fs.Args())
	if err != nil {
		return err
	}
	out, err := textconv.Normalize(string(data), *form)
	if err != nil {
		return err
	}
	_, err = io.WriteString(os.Stdout, out)
	return err
}

func readInput(args []string) ([]byte, error) {
	if len(args) > 1 {
		return nil, fmt.Errorf("expected at most one file argument, got %d", len(args))
	}
	if len(args) == 1 {
		return os.ReadFile(args[0])
	}
	return io.ReadAll(os.Stdin)
}

func usage() {
	fmt.Fprint(os.Stderr, `textconv - encoding conversion and Unicode normalization

Commands:
  convert    -from <enc> -to <enc> [file]
  normalize  -form <NFC|NFD|NFKC|NFKD> [file]
  encodings  list supported encodings

Input is read from stdin when no file is given.
`)
}
